import{_ as n,o as a,c as r,ak as l}from"./chunks/framework.Cmnvp6lV.js";const o="/projects/GoGoPi/en/latest/assets/image1.DIHMMRXl.webp",c="/projects/GoGoPi/en/latest/assets/image2.CC66Y4bJ.webp",h="/projects/GoGoPi/en/latest/assets/image3.Dgk7ZLo6.webp",d="/projects/GoGoPi/en/latest/assets/image4.BCGzlbNs.webp",g="data:image/png;base64,",p="data:image/png;base64,",m="/projects/GoGoPi/en/latest/assets/image7.C0fE251m.webp",A="/projects/GoGoPi/en/latest/assets/image8.C992rd7r.webp",u="/projects/GoGoPi/en/latest/assets/image9.pmSaBG8T.webp",e="data:image/png;base64,",i="data:image/png;base64,",y="/projects/GoGoPi/en/latest/assets/image12.k6vbd1fr.webp",b="/projects/GoGoPi/en/latest/assets/image13.MgO63BzP.webp",k="/projects/GoGoPi/en/latest/assets/image14.DdX0Gh3M.webp",s="/projects/GoGoPi/en/latest/assets/image15.DxOwkwbQ.webp",w="/projects/GoGoPi/en/latest/assets/image16.Erjc5Ekl.webp",v="/projects/GoGoPi/en/latest/assets/image17.Dub4yRsW.webp",f="/projects/GoGoPi/en/latest/assets/image18.DQrDkSi6.webp",C="/projects/GoGoPi/en/latest/assets/image19.BM35rnHb.webp",G="/projects/GoGoPi/en/latest/assets/image20.BZPMyJvV.webp",q="/projects/GoGoPi/en/latest/assets/image21.jKby5H5E.webp",P="/projects/GoGoPi/en/latest/assets/image22.HPwFnG_Q.webp",x="/projects/GoGoPi/en/latest/assets/image23.B6r9YTNi.webp",B="/projects/GoGoPi/en/latest/assets/image24.tFD14u-I.webp",E="/projects/GoGoPi/en/latest/assets/image25.C0Knw_vB.webp",F="/projects/GoGoPi/en/latest/assets/image26.azgCgdgI.webp",W="/projects/GoGoPi/en/latest/assets/image27.D_VdXlB7.webp",N="/projects/GoGoPi/en/latest/assets/image28.Bne5appu.webp",I="/projects/GoGoPi/en/latest/assets/image29.C-cVTxRQ.webp",z="/projects/GoGoPi/en/latest/assets/image30.Coy4-nNH.webp",V="/projects/GoGoPi/en/latest/assets/image31.u7jT5pmo.webp",R="/projects/GoGoPi/en/latest/assets/image32.C0g4NYbL.webp",S="/projects/GoGoPi/en/latest/assets/image33.Csfp4gV5.webp",M="/projects/GoGoPi/en/latest/assets/image34.CKT0TmqU.webp",D="/projects/GoGoPi/en/latest/assets/image35.Cr6jkzsd.webp",X=JSON.parse('{"title":"5. Robot Network Configuration Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/5.Robot Network Configuration Course.md","filePath":"docs/5.Robot Network Configuration Course.md"}'),O={name:"docs/5.Robot Network Configuration Course.md"};function T(H,t,Q,j,U,Z){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="_5-robot-network-configuration-course" tabindex="-1">5. Robot Network Configuration Course <a class="header-anchor" href="#_5-robot-network-configuration-course" aria-label="Permalink to &quot;5. Robot Network Configuration Course&quot;">​</a></h1><p>This tutorial uses GoGoPi as the example robot for network configuration.</p><h2 id="_5-1-network-configuration-overview" tabindex="-1">5.1 Network Configuration Overview <a class="header-anchor" href="#_5-1-network-configuration-overview" aria-label="Permalink to &quot;5.1 Network Configuration Overview&quot;">​</a></h2><p>The robot&#39;s network can be configured in two modes:</p><ol><li><p>AP Mode: The controller creates a hotspot that can be connected to by a smartphone. (Note: This mode does not connect to the external internet.)</p></li><li><p>STA mode: The controller connects directly to a specified hotspot/Wi-Fi network. (This mode allows access to the external internet.)</p></li></ol><p>By default, the robot operates in AP (direct connection) mode. The features and functions of the robot remain the same whether in AP mode or STA (local area network) mode.</p><h2 id="_5-2-ap-direct-connection-mode" tabindex="-1">5.2 AP Direct Connection Mode <a class="header-anchor" href="#_5-2-ap-direct-connection-mode" aria-label="Permalink to &quot;5.2 AP Direct Connection Mode&quot;">​</a></h2><h3 id="_5-2-1-mode-switching-through-phone" tabindex="-1">5.2.1 Mode Switching through Phone <a class="header-anchor" href="#_5-2-1-mode-switching-through-phone" aria-label="Permalink to &quot;5.2.1 Mode Switching through Phone&quot;">​</a></h3><p>Using the Android system as an example, these instructions also apply to iOS.</p><ol><li>Open the <strong>“WonderPi”</strong> app on your phone. Then, go to <strong>&quot;Basic&quot;</strong> and select <strong>&quot;GoGoPi&quot;</strong> or the robot you have.</li></ol><img loading="lazy" height="780" width="1733" src="'+o+'" class="common_img" style="width:800px;"><ol start="2"><li>Tap the <strong>“+”</strong> button in the bottom right corner of the screen, and choose <strong>“Direct Connection Mode”</strong>.</li></ol><img loading="lazy" height="414" width="908" src="'+c+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If you prefer to connect in LAN mode, refer to Section 5.3: Connecting in LAN Mode (optional).</strong></p></div><ol start="3"><li>Tap <strong>“Go to Connect Device Hotspot”</strong>. This will take you to your phone’s settings to connect to the hotspot created by the robot.</li></ol><img loading="lazy" height="569" width="1267" src="'+h+'" class="common_img" style="width:800px;"><ol start="4"><li>Look for a hotspot name starting with <strong>“HW”</strong>. The password is <strong>“hiwonder”</strong>.</li></ol><img loading="lazy" height="1056" width="1280" src="'+d+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>For iOS: Wait until the Wi-Fi icon <img loading="lazy" height="52" width="52" src="'+g+'" class="inline-icon" style="width:30px;"> appears in your phone’s status bar before returning to the app. If you don’t see the device listed, you can refresh by tapping the refresh icon <img loading="lazy" height="52" width="52" src="'+p+'" class="inline-icon" style="width:30px;"> in the upper-right corner of the app.</strong></p></div><ol start="5"><li>Return to the app, and tap the robot icon to enter the mode selection screen.</li></ol><img loading="lazy" height="572" width="1266" src="'+m+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If a pop-up message appears saying “Network Unavailable, Continue Connection?”, simply tap “Keep Connection”.</strong></p></div><ol start="6"><li>If you see a prompt asking <strong>“Switch to and enter the searched interface?”</strong>, it indicates that an incorrect product version was selected in Step 1. Tap <strong>“OK”</strong> to switch directly to the correct version’s mode selection screen.</li></ol><img loading="lazy" height="731" width="1268" src="'+A+'" class="common_img" style="width:800px;"><ol start="7"><li>The mode selection screen appears as shown below:</li></ol><img loading="lazy" height="553" width="1266" src="'+u+'" class="common_img" style="width:800px;"><p>For details on each mode, refer to the documentation provided earlier.</p><h3 id="_5-2-2-switching-via-network-configuration-file" tabindex="-1">5.2.2 Switching via Network Configuration File <a class="header-anchor" href="#_5-2-2-switching-via-network-configuration-file" aria-label="Permalink to &quot;5.2.2 Switching via Network Configuration File&quot;">​</a></h3><ol><li><p>Power on the robot and connect it to the remote control software, VNC.</p></li><li><p>Double-click the terminal icon <img loading="lazy" height="38" width="46" src="'+e+'" class="inline-icon" style="width:30px;"> on the desktop to open the command line terminal.</p></li><li><p>Enter the following command and press Enter to navigate to the configuration file directory.</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox/</span></span></code></pre></div><img loading="lazy" height="22" width="248" src="'+i+'" class="inline-icon"><ol start="4"><li>Enter the command and press Enter to open the configuration file.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><img loading="lazy" height="77" width="1242" src="'+y+'" class="inline-icon"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The configuration file defaults to AP Direct Connection Mode. If all code lines are commented out, it will be set to AP Direct Connection Mode.</strong></p></div><img loading="lazy" height="476" width="748" src="'+b+'" class="common_img" style="width:800px;"><ol start="5"><li>If there are multiple devices nearby, you can modify <code>HW_WIFI_AP_SSID</code> and <code>HW_WIFI_AP_PASSWORD</code> to set a unique name and password for each device. For example, use <strong>“HW-Robot”</strong> as the name and <strong>“hiwonder”</strong> as the password, as shown below.</li></ol><img loading="lazy" height="249" width="748" src="'+k+'" class="inline-icon"><ol start="6"><li>After verifying the entries, press the ESC key, then type <code>:wq</code> to save and exit the file.</li></ol><img loading="lazy" height="84" width="990" src="'+s+'" class="inline-icon"><ol start="7"><li>Next, enter the command <code>vim wifi.py</code> and press Enter to open another configuration file.</li></ol><img loading="lazy" height="33" width="392" src="'+w+'" class="inline-icon"><ol start="8"><li>Change the value of <code>HW_WIFI_AP_GATEWAY</code> to set a new IP address, such as <code>192.168.149.2</code>, for example.</li></ol><img loading="lazy" height="33" width="591" src="'+v+'" class="inline-icon"><ol start="9"><li>After confirming the entries, press the ESC key, then type <code>:wq</code> to save and exit the file.</li></ol><img loading="lazy" height="138" width="986" src="'+f+'" class="inline-icon"><ol start="10"><li>Enter the command <code>sudo systemctl restart wifi.service</code> to restart the robot&#39;s Wi-Fi service.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi.service</span></span></code></pre></div><img loading="lazy" height="71" width="1233" src="'+C+'" class="inline-icon"><ol start="11"><li>Wait for the service to restart. You should see that the hotspot has been successfully updated.</li></ol><img loading="lazy" height="44" width="342" src="'+G+'" class="inline-icon"><ol start="12"><li>To connect using VNC, enter the new IP address in the search bar, and click on the connection icon that appears. Log in with the username <strong>“pi”</strong> and password <strong>“raspberry”</strong>, then click <strong>“OK”</strong> to access the system desktop. (For the Pi5 version, the username is the same as the 4B version, but the password is <strong>“raspberrypi”</strong>.)</li></ol><img loading="lazy" height="353" width="486" src="'+q+'" class="common_img" style="width:800px;"><img loading="lazy" height="687" width="1267" src="'+P+'" class="common_img" style="width:800px;"><h2 id="_5-3-connecting-in-lan-mode-optional" tabindex="-1">5.3 Connecting in LAN Mode (optional) <a class="header-anchor" href="#_5-3-connecting-in-lan-mode-optional" aria-label="Permalink to &quot;5.3 Connecting in LAN Mode (optional)&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Notes:</strong></p><p><strong>1. To configure the LAN mode using a smartphone, you must first enable the phone&#39;s location services.</strong></p><p><strong>2. Switching to LAN mode cannot be done directly through the system&#39;s network settings, as the Wi-Fi has custom configurations. Please follow the instructions in Section 5.3.2 to switch modes using the network configuration file.</strong></p></div><h3 id="_5-3-1-switching-via-the-mobile-app" tabindex="-1">5.3.1 Switching via the Mobile App <a class="header-anchor" href="#_5-3-1-switching-via-the-mobile-app" aria-label="Permalink to &quot;5.3.1 Switching via the Mobile App&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>For LAN mode, please enable location services on your smartphone.</strong></p></div><ol><li>First, connect your phone to Wi-Fi. In this example, we connect to <strong>&quot;Hiwonder_5G&quot;</strong> Wi-Fi. (For dual-band routers with separated frequencies, the Wi-Fi names may differ, such as <strong>&quot;Hiwonder&quot;</strong> for the 2.4G band and <strong>&quot;Hiwonder_5G&quot;</strong> for the 5G band.)</li></ol><img loading="lazy" height="1465" width="1280" src="'+x+'" class="common_img" style="width:800px;"><ol start="2"><li>Open the <strong>&quot;WonderPi&quot;</strong> app on your phone, then select <strong>&quot;Basic&quot;</strong> and <strong>&quot;GoGoPi&quot;</strong>.</li></ol><img loading="lazy" height="780" width="1733" src="'+o+'" class="common_img" style="width:800px;"><ol start="3"><li>Tap the <strong>&quot;+&quot;</strong> button in the bottom right corner, and choose <strong>&quot;LAN Mode&quot;</strong>.</li></ol><img loading="lazy" height="414" width="902" src="'+B+'" class="common_img" style="width:800px;"><ol start="4"><li>The app will prompt you to enter the password for the connected Wi-Fi network. (Please ensure the password is correct, as an incorrect password will result in connection failure.) After entering the password, tap <strong>&quot;OK&quot;</strong>.</li></ol><img loading="lazy" height="415" width="905" src="'+E+'" class="common_img" style="width:800px;"><ol start="5"><li>Tap <strong>&quot;Go to connect device hotspot&quot;</strong>.</li></ol><img loading="lazy" height="554" width="1264" src="'+F+'" class="common_img" style="width:800px;"><ol start="6"><li>Your phone will automatically navigate to the Wi-Fi settings page. Find the hotspot starting with <strong>&quot;HW&quot;</strong> and enter the password <strong>&quot;hiwonder&quot;</strong>. Once connected, tap the <strong>&quot;Return&quot;</strong> button.</li></ol><img loading="lazy" height="295" width="345" src="'+W+'" class="common_img" style="width:800px;"><ol start="7"><li>The app will now begin the connection process.</li></ol><img loading="lazy" height="567" width="1267" src="'+N+'" class="common_img" style="width:800px;"><ol start="8"><li>After a short wait, the robot’s icon will appear on the main screen, and the LED on the expansion board will remain steadily lit.</li></ol><img loading="lazy" height="575" width="1268" src="'+I+'" class="common_img" style="width:800px;"><ol start="9"><li>Press and hold the robot icon in the app to view the robot’s assigned IP address and device ID.</li></ol><img loading="lazy" height="577" width="1267" src="'+z+'" class="common_img" style="width:800px;"><ol start="10"><li><p>Use a remote desktop tool to search for the robot&#39;s IP address and connect to the remote desktop.</p></li><li><p>To switch back to direct connection mode from LAN mode, press and hold the KEY1 button on the expansion board until the blue LED flashes, indicating that the switch is complete.</p></li></ol><h3 id="_5-3-2-switching-via-network-configuration-file" tabindex="-1">5.3.2 Switching via Network Configuration File <a class="header-anchor" href="#_5-3-2-switching-via-network-configuration-file" aria-label="Permalink to &quot;5.3.2 Switching via Network Configuration File&quot;">​</a></h3><ol><li><p>Power on the robot and connect it to the remote control software, NoMachine.</p></li><li><p>Click the terminal icon <img loading="lazy" height="38" width="46" src="'+e+'" class="inline-icon" style="width:30px;"> at the top of the system screen to open the command line terminal.</p></li><li><p>Enter the command and press Enter to access the configuration file directory.</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hiwonder-toolbox</span></span></code></pre></div><img loading="lazy" height="22" width="248" src="'+i+'" class="inline-icon"><ol start="4"><li>Enter the command and press Enter to open the configuration file.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi_conf.py</span></span></code></pre></div><img loading="lazy" height="49" width="727" src="'+V+'" class="inline-icon"><ol start="5"><li>First, change the value of <code>HW_WIFI_MODE</code> to 2:</li></ol><ul><li><p>1 represents Direct Connection Mode</p></li><li><p>2 represents LAN Mode</p></li><li><p>3 represents Direct Sharing Mode</p></li></ul><img loading="lazy" height="25" width="812" src="'+R+'" class="inline-icon"><ol start="6"><li>Next, modify <code>HW_WIFI_STA_SSID</code> and <code>HW_WIFI_STA_PASSWORD</code> to match your router’s Wi-Fi name and password.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Selecting a 5G Wi-Fi signal will provide higher transfer speeds. If there is lag on standard Wi-Fi, consider switching to a 5G signal.</strong></p></div><img loading="lazy" height="227" width="727" src="'+S+'" class="inline-icon"><ol start="7"><li>After confirming the entries are correct, press the ESC key, then type <code>:wq</code> to save and exit the file.</li></ol><img loading="lazy" height="84" width="990" src="'+s+'" class="inline-icon"><img loading="lazy" height="24" width="810" src="'+M+'" class="inline-icon"><ol start="8"><li>Enter the following command to restart the robot&#39;s Wi-Fi service.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wifi.service</span></span></code></pre></div><img loading="lazy" height="23" width="571" src="'+D+'" class="inline-icon"><ol start="9"><li>To switch back to Direct Connection Mode, edit the configuration file again, comment out all lines, save, and restart.</li></ol>',97)])])}const L=n(O,[["render",T]]);export{X as __pageData,L as default};
